INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Using Accessibility Checker Pro + Claude AI to Remediate a Large WordPress Site', 'Equalize Digital Web Accessibility Meetup Los Angeles', 'Tech & Software', 'Courtney Robertson will share a practical case study of running Equalize Digital’s Accessibility Checker Pro across her long-running', 'Courtney Robertson will share a practical case study of running Equalize Digital’s Accessibility Checker Pro across her long-running WordPress site (including a large archive of older posts), then feeding those scan results into Claude Code to automate fixes. Examples include converting YouTube embeds to AblePlayer with VTT transcripts, resolving aria-hidden issues on emojis and UI elements, and other content-level remediation. We’ll examine concrete before-and-after results: what the AI More info: https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/316256195/', '2026-10-20T08:00:00-07:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 33.97, -118.24, 'Equalize Digital Web Accessibility Meetup Los Angeles', 3, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/316256195/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Progress, Not Panic: A Practical Approach to Your Title II Deadline', 'Equalize Digital Web Accessibility Meetup Los Angeles', 'Tech & Software', 'In this practical webinar, Equalize Digital CEO Amber Hinds and COO Chris Hinds will share strategies public sector organizations can use', 'In this practical webinar, Equalize Digital CEO Amber Hinds and COO Chris Hinds will share strategies public sector organizations can use to move their WordPress websites toward accessibility conformance while working within real-world constraints like limited budgets, small teams, legacy code, and competing priorities. Drawing on years of experience auditing and remediating public sector websites and helping organizations build sustainable accessibility practices, Amber and Chris will show you More info: https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/316737477/', '2026-10-29T10:00:00-07:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 33.97, -118.24, 'Equalize Digital Web Accessibility Meetup Los Angeles', 3, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/316737477/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('I Didn’t Realize WCAG Meant That! with Cam Coulter', 'Equalize Digital Web Accessibility Meetup Los Angeles', 'Tech & Software', 'Cam has noticed that sometimes organizational leaders can be quick to adopt WCAG 2.2 AA as an internal standard or policy; however, they', 'Cam has noticed that sometimes organizational leaders can be quick to adopt WCAG 2.2 AA as an internal standard or policy; however, they may do so without really understanding the standard. In particular, they might not realize some important things that WCAG requires and places limitations around. In this session, Cam will draw attention to some requirements that are too frequently overlooked, both to help aspiring accessibility specialists better understand WCAG as well as to help leaders More info: https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/315961115/', '2026-11-05T08:00:00-08:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 33.97, -118.24, 'Equalize Digital Web Accessibility Meetup Los Angeles', 3, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/315961115/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Find & Fix Faster: Accessibility Checker Pro 2.0', 'Equalize Digital Web Accessibility Meetup Los Angeles', 'Tech & Software', 'A lot has changed in Accessibility Checker Pro over the past year. We’ve spent that time rebuilding the plugin around one goal: Helping you', 'A lot has changed in Accessibility Checker Pro over the past year. We’ve spent that time rebuilding the plugin around one goal: Helping you find and fix accessibility issues faster, without pulling you out of WordPress. The redesigned Accessibility Checker helps you spot problems, prioritize your next steps, and track your progress faster, while making issues easier to understand and action. Join us for a deep dive into what’s changed and how Accessibility Checker Pro 2.0 can make your More info: https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/316814409/', '2026-11-12T08:00:00-08:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 33.97, -118.24, 'Equalize Digital Web Accessibility Meetup Los Angeles', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/equalize-digital-web-accessibility-meetup-los-angeles/events/316814409/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
