INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Made to Make · Part 4: A Way of Building Redemptively + Hackathon Recap', 'FaithTech Nashville', 'Founders & Startups', 'This fall we''ve been walking through the new FaithTech Playbook 2.0, one part per night, and we just put it into practice at Hack for the', 'This fall we''ve been walking through the new FaithTech Playbook 2.0, one part per night, and we just put it into practice at Hack for the Community (Nov. 12-13). Never been, or haven''t made it yet this fall? You''re welcome here: this night stands on its own and is a great way to meet the community. **What to Expect** **Eat:** Connect over food: we''ll have pizza, soda, and water. **Learn:** Part 4, A Way of Building Redemptively: how the four stages of the Redemptive Create Cycle fit together. More info: https://www.meetup.com/faithtech-nashville/events/316790668/', '2026-11-17T18:00:00-06:00', 'Greater Nashville Technology Council', '500 Interstate Blvd S #200', 'Nashville', 'TN', '', 36.14, -86.74, 'FaithTech Nashville', 2, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/faithtech-nashville/events/316790668/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Made to Make · Christmas Gathering', 'FaithTech Nashville', 'Founders & Startups', 'Wrapping up Made to Make: a relaxed evening to celebrate the fall together and look ahead to 2027. Haven''t made it to a FaithTech night', 'Wrapping up Made to Make: a relaxed evening to celebrate the fall together and look ahead to 2027. Haven''t made it to a FaithTech night yet? This is an easy first one, and you don''t need to have come this fall to join in. **What to Expect** **Eat:** Food and fellowship to celebrate the season together. **Learn:** A short Advent reflection: our deepest hope is not in what we build. **Build:** Stories from the fall, share your hopes for 2027, and hear how you can help lead FaithTech Nashville More info: https://www.meetup.com/faithtech-nashville/events/316790689/', '2026-12-15T18:00:00-06:00', 'Greater Nashville Technology Council', '500 Interstate Blvd S #200', 'Nashville', 'TN', '', 36.14, -86.74, 'FaithTech Nashville', 2, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/faithtech-nashville/events/316790689/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
